struct Repository:m::ReaderRepository {m::ReaderLibrary value;unsigned reads{},saves{};bool fail{};m::ReaderLibrary load()override{++reads;return value;}void save(const m::ReaderLibrary&v)override{++saves;if(fail)throw std::runtime_error("Synthetic reader save failure");value=v;}};
struct Queue {
 struct Job {std::function<void()>work;std::function<void(std::exception_ptr)>done;std::exception_ptr error;};std::deque<Job>jobs;std::size_t capacity{32};unsigned rejected{},accepted{};
 m::ReaderExecutor executor(){return {[this](auto w,auto d){if(jobs.size()>=capacity){++rejected;return false;}jobs.push_back({std::move(w),std::move(d),{}});++accepted;return true;}};}
 void one(){check(!jobs.empty(),"Synthetic borrowed FIFO job exists");auto job=std::move(jobs.front());jobs.pop_front();try{job.work();}catch(...){job.error=std::current_exception();}job.done(job.error);}
 void drain(){for(unsigned n=0;!jobs.empty();++n){check(n<1000,"Reader installs no automatic retry loop");one();}}
};
